CREATE TABLE rail_provider_passenger(reservation_id UUID NOT NULL REFERENCES rail_provider_reservation(id),passenger_index INTEGER NOT NULL CHECK(passenger_index BETWEEN 0 AND 5),active BOOLEAN NOT NULL,PRIMARY KEY(reservation_id,passenger_index));
-- Existing supplier quantities describe the original whole-party allocation; no entitlement changes.
INSERT INTO rail_provider_passenger SELECT id,generate_series(0,quantity-1),active FROM rail_provider_reservation WHERE status<>'REJECTED';
CREATE TABLE rail_provider_passenger_operation(operation_id UUID PRIMARY KEY,reservation_id UUID NOT NULL REFERENCES rail_provider_reservation(id),receipt JSONB NOT NULL,CHECK((receipt->>'operationId')::uuid=operation_id AND (receipt->>'reservationId')::uuid=reservation_id AND receipt->>'mode'='MOCK'));
CREATE TRIGGER immutable_passenger_operation BEFORE UPDATE OR DELETE ON rail_provider_passenger_operation FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
CREATE TABLE rail_ticket_cancellation_result(quote_id UUID PRIMARY KEY REFERENCES rail_ticket_cancellation_quote(id),booking_id UUID NOT NULL REFERENCES rail_ticket_booking(id),created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),payload JSONB NOT NULL,CHECK((payload->>'quoteId')::uuid=quote_id AND payload->>'status' IN('SUCCEEDED','NOT_DUE')));
-- Preserve already completed whole-party refunds from the previously verified lifecycle.
INSERT INTO rail_ticket_cancellation_result(quote_id,booking_id,payload)
 SELECT (payload->'cancellation'->'quote'->>'id')::uuid,id,
 jsonb_build_object('quoteId',payload->'cancellation'->'quote'->'id','passengerIndexes',(SELECT jsonb_agg(i) FROM generate_series(0,jsonb_array_length(payload->'quote'->'selection'->'passengers')-1) AS i),'refundAmount',payload->'cancellation'->'quote'->'refundAmount','status',payload->'refund','reference',payload->'refundReference','completedAt',payload->'updatedAt')
 FROM rail_ticket_booking WHERE status='CANCELLED' AND payload->>'step'='DONE' AND payload->>'refund' IN('SUCCEEDED','NOT_DUE') AND payload->'cancellation'<>'null'::jsonb;
CREATE INDEX rail_cancellation_history ON rail_ticket_cancellation_result(booking_id,created_at);
CREATE TRIGGER immutable_passenger_result BEFORE UPDATE OR DELETE ON rail_ticket_cancellation_result FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
CREATE TABLE rail_ticket_document_revision(id UUID PRIMARY KEY,booking_id UUID NOT NULL REFERENCES rail_ticket_booking(id),revision INTEGER NOT NULL CHECK(revision BETWEEN 0 AND 6),payload JSONB NOT NULL,UNIQUE(booking_id,revision),CHECK((payload->>'id')::uuid=id AND (payload->>'bookingId')::uuid=booking_id AND (payload->>'byteLength')::integer BETWEEN 1 AND 32768));
CREATE TRIGGER immutable_rail_document_revision BEFORE UPDATE OR DELETE ON rail_ticket_document_revision FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
CREATE OR REPLACE FUNCTION guard_rail_ticket_booking() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Rail booking history is immutable'; END IF;
 IF NEW.id<>OLD.id OR NEW.customer_id<>OLD.customer_id OR NEW.quote_id<>OLD.quote_id OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1
 OR (NEW.payload-'version'-'updatedAt'-'status'-'payment'-'reservation'-'refund'-'step'-'supplierReference'-'paymentReference'-'refundReference'-'failureCode'-'cancellation'-'cancelledPassengerIndexes') IS DISTINCT FROM (OLD.payload-'version'-'updatedAt'-'status'-'payment'-'reservation'-'refund'-'step'-'supplierReference'-'paymentReference'-'refundReference'-'failureCode'-'cancellation'-'cancelledPassengerIndexes')
 OR NOT (coalesce(OLD.payload->'cancelledPassengerIndexes','[]'::jsonb) <@ coalesce(NEW.payload->'cancelledPassengerIndexes','[]'::jsonb))
 OR (OLD.payload->'cancellation'<>'null'::jsonb AND ((NEW.payload->'cancellation' #- '{quote,passengerIndexes}') IS DISTINCT FROM (OLD.payload->'cancellation' #- '{quote,passengerIndexes}') OR coalesce(NEW.payload#>'{cancellation,quote,passengerIndexes}','null'::jsonb) IS DISTINCT FROM coalesce(OLD.payload#>'{cancellation,quote,passengerIndexes}','null'::jsonb)) AND NOT (OLD.status='ISSUED' AND OLD.payload->>'step'='DONE' AND EXISTS(SELECT 1 FROM rail_ticket_cancellation_result r WHERE r.quote_id=(OLD.payload->'cancellation'->'quote'->>'id')::uuid AND r.booking_id=OLD.id))) THEN RAISE EXCEPTION 'Rail booking input/version guard'; END IF; RETURN NEW; END $$;
